class TreeNode(var `val`: Int) {
    var left: TreeNode? = null
    var right: TreeNode? = null
}

fun levelOrder(root: TreeNode?): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    if (root == null) return result
    val queue = ArrayDeque<TreeNode>()
    queue.addLast(root)
    while (queue.isNotEmpty()) {
        val size = queue.size                       // number of nodes in this level
        val level = ArrayList<Int>(size)
        repeat(size) {
            val node = queue.removeFirst()
            level.add(node.`val`)
            node.left?.let { queue.addLast(it) }
            node.right?.let { queue.addLast(it) }
        }
        result.add(level)
    }
    return result
}
// Time: O(n)   Space: O(w)

fun bfs(root: TreeNode?) {
    if (root == null) return
    val queue = ArrayDeque<TreeNode>()
    queue.addLast(root)
    while (queue.isNotEmpty()) {
        val node = queue.removeFirst()
        // process node
        node.left?.let { queue.addLast(it) }
        node.right?.let { queue.addLast(it) }
    }
}
// Use this when you do not care which level a node belongs to

fun bfsWithDepth(root: TreeNode?) {
    if (root == null) return
    val queue = ArrayDeque<Pair<TreeNode, Int>>()
    queue.addLast(Pair(root, 1))
    while (queue.isNotEmpty()) {
        val (node, depth) = queue.removeFirst()
        // process node at 'depth'
        node.left?.let { queue.addLast(Pair(it, depth + 1)) }
        node.right?.let { queue.addLast(Pair(it, depth + 1)) }
    }
}
// Alternative to the level size trick when you need the depth per node

