fun zigzagLevelOrder(root: TreeNode?): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    if (root == null) return result
    val queue = ArrayDeque<TreeNode>()
    queue.addLast(root)
    var leftToRight = true
    while (queue.isNotEmpty()) {
        val level = ArrayList<Int>()
        repeat(queue.size) {
            val node = queue.removeFirst()
            level.add(node.`val`)
            node.left?.let { queue.addLast(it) }
            node.right?.let { queue.addLast(it) }
        }
        if (!leftToRight) level.reverse()
        result.add(level)
        leftToRight = !leftToRight
    }
    return result
}
// Time: O(n)   Space: O(n)

fun averageOfLevels(root: TreeNode?): List<Double> {
    val result = mutableListOf<Double>()
    if (root == null) return result
    val queue = ArrayDeque<TreeNode>()
    queue.addLast(root)
    while (queue.isNotEmpty()) {
        val size = queue.size
        var sum = 0L                                // Long avoids overflow
        repeat(size) {
            val node = queue.removeFirst()
            sum += node.`val`
            node.left?.let { queue.addLast(it) }
            node.right?.let { queue.addLast(it) }
        }
        result.add(sum.toDouble() / size)
    }
    return result
}
// Time: O(n)   Space: O(w)

fun rightSideView(root: TreeNode?): List<Int> {
    val result = mutableListOf<Int>()
    if (root == null) return result
    val queue = ArrayDeque<TreeNode>()
    queue.addLast(root)
    while (queue.isNotEmpty()) {
        val size = queue.size
        for (i in 0 until size) {
            val node = queue.removeFirst()
            if (i == size - 1) result.add(node.`val`)   // last node of the level
            node.left?.let { queue.addLast(it) }
            node.right?.let { queue.addLast(it) }
        }
    }
    return result
}
// Time: O(n)   Space: O(w)
// For the left side view, take i == 0 instead

fun largestValues(root: TreeNode?): List<Int> {
    val result = mutableListOf<Int>()
    if (root == null) return result
    val queue = ArrayDeque<TreeNode>()
    queue.addLast(root)
    while (queue.isNotEmpty()) {
        var best = Int.MIN_VALUE
        repeat(queue.size) {
            val node = queue.removeFirst()
            best = maxOf(best, node.`val`)
            node.left?.let { queue.addLast(it) }
            node.right?.let { queue.addLast(it) }
        }
        result.add(best)
    }
    return result
}
// Time: O(n)   Space: O(w)

fun minDepth(root: TreeNode?): Int {
    if (root == null) return 0
    val queue = ArrayDeque<TreeNode>()
    queue.addLast(root)
    var depth = 1
    while (queue.isNotEmpty()) {
        repeat(queue.size) {
            val node = queue.removeFirst()
            if (node.left == null && node.right == null) return depth   // first leaf found
            node.left?.let { queue.addLast(it) }
            node.right?.let { queue.addLast(it) }
        }
        depth++
    }
    return depth
}
// Time: O(n) worst case, often much less   Space: O(w)
// BFS stops at the shallowest leaf, while DFS must check every branch

