class Node(var `val`: Int) {
    var left: Node? = null
    var right: Node? = null
    var next: Node? = null
}

fun connect(root: Node?): Node? {
    if (root == null) return null
    val queue = ArrayDeque<Node>()
    queue.addLast(root)
    while (queue.isNotEmpty()) {
        var prev: Node? = null
        repeat(queue.size) {
            val node = queue.removeFirst()
            prev?.next = node                       // link previous node to this one
            prev = node
            node.left?.let { queue.addLast(it) }
            node.right?.let { queue.addLast(it) }
        }
    }
    return root
}
// Time: O(n)   Space: O(w)

fun connectPerfect(root: Node?): Node? {
    var leftmost = root
    while (leftmost?.left != null) {
        var head = leftmost
        while (head != null) {
            head.left!!.next = head.right
            val nextHead = head.next
            if (nextHead != null) head.right!!.next = nextHead.left
            head = nextHead
        }
        leftmost = leftmost.left
    }
    return root
}
// Time: O(n)   Space: O(1)
// Uses the next pointers built on the previous level instead of a queue

fun levelOrderSuccessor(root: TreeNode?, key: Int): TreeNode? {
    if (root == null) return null
    val queue = ArrayDeque<TreeNode>()
    queue.addLast(root)
    while (queue.isNotEmpty()) {
        val node = queue.removeFirst()
        node.left?.let { queue.addLast(it) }
        node.right?.let { queue.addLast(it) }
        if (node.`val` == key) return queue.firstOrNull()   // next node in the queue
    }
    return null
}
// Time: O(n)   Space: O(w)

fun isCousins(root: TreeNode?, x: Int, y: Int): Boolean {
    if (root == null) return false
    val queue = ArrayDeque<TreeNode>()
    queue.addLast(root)
    while (queue.isNotEmpty()) {
        var foundX = false
        var foundY = false
        repeat(queue.size) {
            val node = queue.removeFirst()
            if (node.`val` == x) foundX = true
            if (node.`val` == y) foundY = true
            val l = node.left
            val r = node.right
            // same parent means siblings, not cousins
            if (l != null && r != null &&
                ((l.`val` == x && r.`val` == y) || (l.`val` == y && r.`val` == x))) return false
            if (l != null) queue.addLast(l)
            if (r != null) queue.addLast(r)
        }
        if (foundX && foundY) return true           // same level, different parents
        if (foundX || foundY) return false          // found on different levels
    }
    return false
}
// Time: O(n)   Space: O(w)

fun widthOfBinaryTree(root: TreeNode?): Int {
    if (root == null) return 0
    var best = 0L
    val queue = ArrayDeque<Pair<TreeNode, Long>>()
    queue.addLast(Pair(root, 0L))
    while (queue.isNotEmpty()) {
        val first = queue.first().second            // index of the leftmost node
        var lastNorm = 0L
        repeat(queue.size) {
            val (node, idx) = queue.removeFirst()
            val norm = idx - first                  // normalize to avoid overflow
            lastNorm = norm
            node.left?.let { queue.addLast(Pair(it, 2 * norm)) }
            node.right?.let { queue.addLast(Pair(it, 2 * norm + 1)) }
        }
        best = maxOf(best, lastNorm + 1)
    }
    return best.toInt()
}
// Time: O(n)   Space: O(w)
// Index children like a heap: left = 2i, right = 2i + 1, nulls are counted implicitly

fun isCompleteTree(root: TreeNode?): Boolean {
    if (root == null) return true
    val queue = ArrayDeque<TreeNode?>()
    queue.addLast(root)
    var seenNull = false
    while (queue.isNotEmpty()) {
        val node = queue.removeFirst()
        if (node == null) {
            seenNull = true                         // after the first gap there must be no nodes
        } else {
            if (seenNull) return false
            queue.addLast(node.left)                // null children are added too
            queue.addLast(node.right)
        }
    }
    return true
}
// Time: O(n)   Space: O(w)

import java.util.TreeMap

fun verticalOrder(root: TreeNode?): List<List<Int>> {
    if (root == null) return emptyList()
    val columns = TreeMap<Int, MutableList<Int>>()
    val queue = ArrayDeque<Pair<TreeNode, Int>>()
    queue.addLast(Pair(root, 0))
    while (queue.isNotEmpty()) {
        val (node, col) = queue.removeFirst()
        columns.getOrPut(col) { mutableListOf() }.add(node.`val`)
        node.left?.let { queue.addLast(Pair(it, col - 1)) }
        node.right?.let { queue.addLast(Pair(it, col + 1)) }
    }
    return columns.values.toList()
}
// Time: O(n log n) because of TreeMap   Space: O(n)
// BFS keeps nodes in the same column in top-to-bottom, left-to-right order

class NaryNode(var `val`: Int) {
    var children: List<NaryNode> = emptyList()
}

fun levelOrderNary(root: NaryNode?): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    if (root == null) return result
    val queue = ArrayDeque<NaryNode>()
    queue.addLast(root)
    while (queue.isNotEmpty()) {
        val level = ArrayList<Int>()
        repeat(queue.size) {
            val node = queue.removeFirst()
            level.add(node.`val`)
            for (child in node.children) queue.addLast(child)
        }
        result.add(level)
    }
    return result
}
// Time: O(n)   Space: O(w)

fun deepestLeavesSum(root: TreeNode?): Int {
    if (root == null) return 0
    val queue = ArrayDeque<TreeNode>()
    queue.addLast(root)
    var levelSum = 0
    while (queue.isNotEmpty()) {
        levelSum = 0                                // reset for each level
        repeat(queue.size) {
            val node = queue.removeFirst()
            levelSum += node.`val`
            node.left?.let { queue.addLast(it) }
            node.right?.let { queue.addLast(it) }
        }
    }
    return levelSum                                 // the last level processed
}
// Time: O(n)   Space: O(w)
